select case when budget >= 3617000 then 'high' when budget >= 833000 then 'mid' else 'low' end as budget_bucket, dept_name, round(avg(budget), 2) as avg_budget, sum(case when location = 'London' then 1 else 0 end) as london_count, sum(case when dept_name = 'Legal' then 1 else 0 end) as legal_count from departments group by case when budget >= 3617000 then 'high' when budget >= 833000 then 'mid' else 'low' end, dept_name having round(avg(budget), 2) >= 67 order by avg_budget desc, london_count asc
